package com.adib.maintenance;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.graphics.*;import android.media.ExifInterface;import android.util.Base64;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
final class NativeImageSupport {
 static final int PICK_IMAGE=7410,MAX_UPLOAD=5*1024*1024,MAX_NATIVE_IMAGE=200*1024;
 static final ExecutorService IO=Executors.newFixedThreadPool(2);
 interface Transport {JSONObject call(String method,String path,JSONObject body)throws Exception;}
 static Transport transport=(m,p,b)->{if(Boolean.getBoolean("adib.testing")){if(m.equals("GET"))return new JSONObject().put("ok",true).put("images",new JSONArray());throw new IOException("Test image transport blocks writes");}return TaskManagementActivity.httpWithTimeout(m,p,b,90000);};
 static final class Draft {final ArrayList<JSONObject> images=new ArrayList<>();boolean busy;boolean has(){return !images.isEmpty();}synchronized JSONArray upload()throws Exception{JSONArray result=new JSONArray();for(JSONObject item:new ArrayList<>(images)){String id=item.optString("fileUploadId","");if(id.isEmpty()||System.currentTimeMillis()-item.optLong("uploadAt")>50*60000L){JSONObject upload=transport.call("POST","/api/image-upload",new JSONObject().put("image",item));if(upload==null||upload.optString("fileUploadId").isEmpty())throw new IOException("Yükləmə təsdiqlənmədi. Şəkillər seçilmiş olaraq qalır.");id=upload.getString("fileUploadId");item.put("fileUploadId",id).put("uploadAt",System.currentTimeMillis());}result.put(new JSONObject().put("type","file_upload").put("file_upload_id",id));}return result;}}
 static final class Wire {final byte[] bytes;final String contentType;Wire(byte[] b,String t){bytes=b;contentType=t;}}
 static Wire wire(String url,String method,String body)throws Exception{JSONObject json;try{json=new JSONObject(body);}catch(Exception e){return null;}JSONObject image=json.optJSONObject("__adibMultipart");if(image==null)return null;URL u=new URL(url);if(!u.getProtocol().equals("https")||!u.getHost().equals("api.notion.com")||!u.getPath().matches("/v1/file_uploads/[a-fA-F0-9-]{36}/send")||!method.equals("POST"))throw new IOException("Yanlış yükləmə ünvanı");String data=image.optString("data"),mime=image.optString("mime");if(data.isEmpty()||data.length()>((MAX_UPLOAD+2)/3)*4||!data.matches("[A-Za-z0-9+/]+={0,2}")||data.length()%4!=0)throw new IOException("Şəkil 5 MB-dan çox olmamalıdır");byte[] bytes=Base64.decode(data,Base64.NO_WRAP);if(bytes.length>MAX_UPLOAD||!mime.equals(detect(bytes)))throw new IOException("Yanlış şəkil formatı");String name=image.optString("name","image.jpg").replaceAll("[\\r\\n\\\"\\\\/\\x00-\\x1f]","_");if(name.length()>120)name=name.substring(0,120);String boundary="ADIBImageBoundary7e18b214";ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+name+"\"\r\nContent-Type: "+mime+"\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(bytes);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));return new Wire(out.toByteArray(),"multipart/form-data; boundary="+boundary);}
 static String detect(byte[] b){if(b.length<12)return "";if((b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return "image/jpeg";if((b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "image/png";String s=new String(b,0,12,StandardCharsets.ISO_8859_1);if(s.startsWith("GIF87a")||s.startsWith("GIF89a"))return "image/gif";if(s.startsWith("RIFF")&&s.substring(8).equals("WEBP"))return "image/webp";return "";}
 static byte[] readLimited(InputStream in,int maximum)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>maximum)throw new IOException("Fayl çox böyükdür");out.write(b,0,n);}return out.toByteArray();}
 static JSONObject readPhoto(Context context,Uri uri)throws Exception{return readPhoto(context,uri,MAX_NATIVE_IMAGE);}
 static JSONObject readPhoto(Context context,Uri uri,int target)throws Exception{final int limit=Math.max(100*1024,Math.min(MAX_NATIVE_IMAGE,target));byte[] raw;try(InputStream in=context.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Şəkli açmaq mümkün olmadı");raw=readLimited(in,30*1024*1024);}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Seçilmiş fayl şəkil deyil");options.inJustDecodeBounds=false;options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1600)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,options);if(bitmap==null)throw new IOException("Şəkli oxumaq mümkün olmadı");try{ExifInterface exif=new ExifInterface(new ByteArrayInputStream(raw));int orientation=exif.getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);Matrix matrix=new Matrix();switch(orientation){case 2:matrix.setScale(-1,1);break;case 3:matrix.setRotate(180);break;case 4:matrix.setScale(1,-1);break;case 5:matrix.setRotate(90);matrix.postScale(-1,1);break;case 6:matrix.setRotate(90);break;case 7:matrix.setRotate(270);matrix.postScale(-1,1);break;case 8:matrix.setRotate(270);break;}if(!matrix.isIdentity()){Bitmap oriented=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(oriented!=bitmap){bitmap.recycle();bitmap=oriented;}}}catch(IOException ignored){}byte[] compressed=null;while(true){for(int quality:new int[]{82,70,58,46}){ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,quality,out);compressed=out.toByteArray();if(compressed.length<=limit)break;}if(compressed.length<=limit)break;if(Math.max(bitmap.getWidth(),bitmap.getHeight())<=128){bitmap.recycle();throw new IOException("Şəkli 200 KB-a endirmək alınmadı");}Bitmap next=Bitmap.createScaledBitmap(bitmap,Math.max(1,(int)(bitmap.getWidth()*.75)),Math.max(1,(int)(bitmap.getHeight()*.75)),true);bitmap.recycle();bitmap=next;}bitmap.recycle();return new JSONObject().put("name","ADIB-image-"+System.currentTimeMillis()+".jpg").put("mime","image/jpeg").put("data",Base64.encodeToString(compressed,Base64.NO_WRAP));}
 static int dp(Context c,int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}
 static void preview(LinearLayout root,Draft draft,Runnable change){root.removeAllViews();for(JSONObject image:new ArrayList<>(draft.images)){LinearLayout item=new LinearLayout(root.getContext());ImageView view=new ImageView(root.getContext());byte[] bytes=Base64.decode(image.optString("data"),Base64.NO_WRAP);BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=8;view.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length,o));view.setScaleType(ImageView.ScaleType.CENTER_CROP);item.addView(view,new LinearLayout.LayoutParams(dp(root.getContext(),72),dp(root.getContext(),72)));Button remove=new Button(root.getContext());remove.setText("×");remove.setContentDescription("Şəkli silin");remove.setEnabled(!draft.busy);remove.setOnClickListener(v->{if(draft.busy)return;draft.images.remove(image);preview(root,draft,change);change.run();});item.addView(remove,new LinearLayout.LayoutParams(dp(root.getContext(),44),dp(root.getContext(),44)));root.addView(item);}}
 static boolean safeUrl(String value){try{URI u=new URI(value);return "https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&!u.getHost().equals("localhost")&&!u.getHost().matches("[0-9.:]+")&&u.getPort()==-1;}catch(Exception e){return false;}}
 static void showImages(Activity activity,LinearLayout parent,JSONArray images){if(images==null)return;for(int i=0;i<images.length();i++){JSONObject item=images.optJSONObject(i);if(item!=null)addImage(activity,parent,item,-1,160);}}
 static void showCommentImages(Activity activity,LinearLayout parent,JSONArray images){if(images==null)return;HorizontalScrollView scroll=new HorizontalScrollView(activity);scroll.setHorizontalScrollBarEnabled(false);scroll.setTag("comment-image-strip");LinearLayout row=new LinearLayout(activity);row.setOrientation(LinearLayout.HORIZONTAL);scroll.addView(row);for(int i=0;i<images.length();i++){JSONObject item=images.optJSONObject(i);if(item!=null)addImage(activity,row,item,112,88);}if(row.getChildCount()>0)parent.addView(scroll,new LinearLayout.LayoutParams(-2,-2));}
 static final LinkedHashMap<String,String> photoMetadata=new LinkedHashMap<>();
 static synchronized JSONObject photoMetadata(String owner,String id){try{String raw=photoMetadata.get(owner+":"+id);return raw==null?null:new JSONObject(raw);}catch(Exception e){return null;}}
 static synchronized void cachePhotoMetadata(String owner,String id,JSONObject value){if(!owner.equals(AccountSession.suffix()))return;String key=owner+":"+id;photoMetadata.remove(key);photoMetadata.put(key,value.toString());while(photoMetadata.size()>60)photoMetadata.remove(photoMetadata.keySet().iterator().next());}
 static final android.util.LruCache<String,Bitmap> thumbnails=new android.util.LruCache<String,Bitmap>(8*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};
 static void addImage(Activity activity,LinearLayout parent,JSONObject item,int width,int height){String url=item.optString("url");if(!safeUrl(url))return;LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);Button show=new Button(activity);show.setText("📷 "+item.optString("name","Foto")+" · Şou");Button original=new Button(activity);original.setText("Orijinalı aç");original.setOnClickListener(v->{try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception ignored){}});box.addView(show);box.addView(original);parent.addView(box,new LinearLayout.LayoutParams(width<0?width:dp(activity,width),-2));String owner=AccountSession.suffix(),cacheKey=owner+":"+url.split("\\?")[0];
 show.setOnClickListener(v->{show.setEnabled(false);ImageView view=new ImageView(activity);view.setContentDescription("Şəkil");view.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(view,new LinearLayout.LayoutParams(-1,dp(activity,height)));Bitmap cached=thumbnails.get(cacheKey);if(cached!=null){view.setImageBitmap(cached);return;}show.setText("Birbaşa yüklənir Notion…");if(Boolean.getBoolean("adib.testing"))return;IO.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();byte[] bytes;try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(12000);if(c.getResponseCode()!=200)throw new IOException("Link köhnəlib. Şəkilinizi yeniləyin.");try(InputStream in=c.getInputStream()){bytes=readLimited(in,30*1024*1024);}}finally{c.disconnect();}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inJustDecodeBounds=false;o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>512)o.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap==null)throw new IOException("Fotonu oxumaq alınmadı");if(!owner.equals(AccountSession.suffix()))return;thumbnails.put(cacheKey,bitmap);activity.runOnUiThread(()->{if(!activity.isDestroyed()&&view.getParent()!=null&&owner.equals(AccountSession.suffix())){view.setImageBitmap(bitmap);show.setText("Foto yükləndi");}});}catch(Exception e){activity.runOnUiThread(()->{if(!activity.isDestroyed()){box.removeView(view);show.setEnabled(true);show.setText("Açmaq alınmadı. Şəkilinizi yeniləyin.");}});}});});}
}
